package cn.bidcheck.verification.engine;

import cn.bidcheck.domain.Domain.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static cn.bidcheck.verification.engine.VerificationTypes.*;

class VisualMarkReviewTest {
    private static final String COMPANY="北方甲建设有限公司";
    private EvidenceCorpus corpus(){return new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(new Document("bid","p","BID","投标文件.pdf",1,"sha","",cn.bidcheck.compat.Java8Api.listOf(new Page(1,"投标文件\n项目名称：北方新城装修工程\n投标人："+COMPANY,"PAGE","TEXT",""), new Page(2,"本项目授权委托书\n项目名称：北方新城装修工程\n投标人（盖章）："+COMPANY,"PAGE","TEXT","")),cn.bidcheck.compat.Java8Api.listOf())));}
    private Rule rule(){return new Rule("mark","授权委托书盖章位置","VISUAL",COMPANY,"seal","","","",cn.bidcheck.compat.Java8Api.mapOf("documentType", "授权委托书"),"须盖章","",cn.bidcheck.compat.Java8Api.listOf());}
    private Map<String,Object> observation(EvidenceCorpus c){Source s=c.all.stream().filter(x->x.evidence().page()==2).findFirst().orElseThrow(java.util.NoSuchElementException::new);return linked(
            "id","observation","obligationId","mark","documentId","bid","location",2,"locationType","PAGE","imageHash","img","type","SEAL","label",COMPANY,"value","","observedValue","","readability","NOT_OBSERVED",
            "requestedTask","SEAL_VISIBILITY","requestedFields",cn.bidcheck.compat.Java8Api.listOf(COMPANY),"requestedSourceIds",cn.bidcheck.compat.Java8Api.listOf(s.id()),
            "source",linked("documentId","bid","documentHash","sha","documentVersion",1,"page",2,"renderedSha256","img","renderedWidth",100,"renderedHeight",100,"roiApplied",false,
                    "transform",cn.bidcheck.compat.Java8Api.mapOf("cropX", 0, "cropY", 0, "cropWidth", 100, "cropHeight", 100)));}
    private RuleEvaluator evaluator(EvidenceCorpus c,List<Map<String,Object>> observations){return new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),c,cn.bidcheck.compat.Java8Api.mapOf("visualObservations", observations));}
    @Test void fullPageBoundNegativeIsRiskNotAutomaticRejection(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();cn.bidcheck.verification.engine.RuleEvaluator e=evaluator(c,cn.bidcheck.compat.Java8Api.listOf(observation(c)));Decision d=e.evaluate(rule());assertEquals("FAIL",d.status(),d.toString());assertEquals(false,d.proof().get("automaticRejection"));assertEquals("NOT_OBSERVED",d.proof().get("observationOutcome"));assertTrue(d.evidences().stream().anyMatch(x->x.anchor().equals("image:img")));assertTrue(e.visualRequests.isEmpty());}
    @Test void unreadableCannotBecomeAbsenceOrPass(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> o=observation(c);o.put("readability","UNREADABLE");cn.bidcheck.verification.engine.RuleEvaluator e=evaluator(c,cn.bidcheck.compat.Java8Api.listOf(o));Decision d=e.evaluate(rule());assertEquals("UNDETERMINED",d.status());assertEquals("VISUAL_MARK_UNREADABLE",d.gaps().get(0).code());assertTrue(e.visualRequests.isEmpty());}
    @Test void notObservedBecauseImageIsUnclearCannotBeNegative(){for(String limitation:cn.bidcheck.compat.Java8Api.listOf("印章区域模糊，无法辨识", "盖章位置被裁切，未观察到印章", "印章处在裁剪区域外，未观察到")){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> o=observation(c);o.put("modelLimitations",cn.bidcheck.compat.Java8Api.listOf(limitation));cn.bidcheck.verification.engine.RuleEvaluator e=evaluator(c,cn.bidcheck.compat.Java8Api.listOf(o));Decision d=e.evaluate(rule());assertEquals("UNDETERMINED",d.status(),limitation);assertEquals("VISUAL_MARK_UNREADABLE",d.gaps().get(0).code());assertTrue(e.visualRequests.isEmpty());}}
    @Test void contradictoryClearObservationPreventsNegativeAndPositiveConclusion(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> no=observation(c);java.util.Map<java.lang.String, java.lang.Object> yes=observation(c);yes.put("id","positive");yes.put("readability","CLEAR");yes.put("value",COMPANY);yes.put("observedValue",COMPANY);yes.put("sourceBbox",cn.bidcheck.compat.Java8Api.listOf(1, 1, 30, 30));Decision d=evaluator(c,cn.bidcheck.compat.Java8Api.listOf(no, yes)).evaluate(rule());assertEquals("UNDETERMINED",d.status());assertEquals("VISUAL_MARK_OBSERVATION_CONFLICT",d.gaps().get(0).code());}
    @Test void unreadableConflictCannotBeCountedAsProvedAbsence(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> no=observation(c);java.util.Map<java.lang.String, java.lang.Object> other=observation(c);other.put("id","blur");other.put("readability","UNREADABLE");assertEquals("VISUAL_MARK_OBSERVATION_CONFLICT",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(no, other)).evaluate(rule()).gaps().get(0).code());}
    @Test void partialConflictsWithNegative(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> no=observation(c);java.util.Map<java.lang.String, java.lang.Object> other=observation(c);other.put("readability","PARTIAL");other.put("value","北方");other.put("observedValue","北方");other.put("sourceBbox",cn.bidcheck.compat.Java8Api.listOf(1, 1, 30, 30));assertEquals("UNDETERMINED",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(no, other)).evaluate(rule()).status());}
    @Test void anotherSubjectCannotSupplyNegative(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> o=observation(c);o.put("requestedFields",cn.bidcheck.compat.Java8Api.listOf("另一公司"));cn.bidcheck.verification.engine.RuleEvaluator e=evaluator(c,cn.bidcheck.compat.Java8Api.listOf(o));assertEquals("VISUAL_OBSERVATION_REQUIRED",e.evaluate(rule()).gaps().get(0).code());assertFalse(e.visualRequests.isEmpty());}
    @Test void anotherPageCannotSupplyNegative(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> o=observation(c);o.put("location",1);assertNotEquals("FAIL",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(o)).evaluate(rule()).status());}
    @Test void wrongObligationCannotSupplyNegative(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> o=observation(c);o.put("obligationId","other");assertNotEquals("FAIL",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(o)).evaluate(rule()).status());}
    @Test void wrongSourceIdentifierCannotSupplyNegative(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> o=observation(c);o.put("requestedSourceIds",cn.bidcheck.compat.Java8Api.listOf("unrelated"));assertNotEquals("FAIL",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(o)).evaluate(rule()).status());}
    @Test void wrongTypeCannotSupplyNegative(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> o=observation(c);o.put("type","FIELD");assertNotEquals("FAIL",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(o)).evaluate(rule()).status());}
    @Test void wrongTaskCannotSupplyNegative(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> o=observation(c);o.put("requestedTask","SIGNATURE_VISIBILITY");assertNotEquals("FAIL",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(o)).evaluate(rule()).status());}
    @Test void staleVersionHashAndCroppedImagesCannotSupplyNegative(){for(String change:cn.bidcheck.compat.Java8Api.listOf("version", "hash", "cropFlag", "cropTransform", "missingVersion", "missingSourceId")){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> o=observation(c);Map<String,Object> origin=new LinkedHashMap<>((Map<String,Object>)o.get("source"));o.put("source",origin);switch (change) {case "version":origin.put("documentVersion",2); break;case "hash":origin.put("documentHash","old"); break;case "cropFlag":origin.put("roiApplied",true); break;case "cropTransform":origin.put("transform",cn.bidcheck.compat.Java8Api.mapOf("cropX", 1, "cropY", 0, "cropWidth", 99, "cropHeight", 100)); break;case "missingVersion":origin.remove("documentVersion"); break;case "missingSourceId":origin.remove("documentId"); break;}assertNotEquals("FAIL",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(o)).evaluate(rule()).status(),change);}}
    @Test void additionalUnobservedCandidatePagePreventsAbsenceConclusion(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();Document doc=c.documents.get(0);List<Page> pages=new ArrayList<>(doc.pages());pages.add(new Page(3,"本项目授权委托书\n项目名称：北方新城装修工程\n投标人（盖章）："+COMPANY,"PAGE","TEXT",""));cn.bidcheck.verification.engine.EvidenceCorpus extended=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(new Document(doc.id(),doc.projectId(),doc.role(),doc.name(),doc.version(),doc.sha256(),doc.createdAt(),pages,cn.bidcheck.compat.Java8Api.listOf())));cn.bidcheck.verification.engine.RuleEvaluator e=evaluator(extended,cn.bidcheck.compat.Java8Api.listOf(observation(extended)));assertEquals("UNDETERMINED",e.evaluate(rule()).status());assertTrue(e.visualRequests.stream().anyMatch(r->Integer.valueOf(3).equals(r.get("location"))));}
    @Test void clearSealStillPassesWithoutAuthenticityAssessment(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();java.util.Map<java.lang.String, java.lang.Object> o=observation(c);o.put("readability","CLEAR");o.put("value",COMPANY);o.put("observedValue",COMPANY);o.put("sourceBbox",cn.bidcheck.compat.Java8Api.listOf(1, 1, 30, 30));o.put("modelLimitations",cn.bidcheck.compat.Java8Api.listOf("无法核实印章真伪"));assertEquals("PASS",evaluator(c,cn.bidcheck.compat.Java8Api.listOf(o)).evaluate(rule()).status());}
    @Test void ninthCandidateIsNotHiddenByEightRequestWindow(){
        Document original=corpus().documents.get(0);List<Page> pages=new ArrayList<>(original.pages());for(int page=3;page<=10;page++)pages.add(new Page(page,original.pages().get(1).text(),"PAGE","TEXT",""));
        EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(new Document(original.id(),original.projectId(),original.role(),original.name(),1,"sha","",pages,cn.bidcheck.compat.Java8Api.listOf())));List<Map<String,Object>> observations=new ArrayList<>();
        for(int page=2;page<=9;page++){Map<String,Object> o=observation(c);o.put("location",page);o.put("id","negative-"+page);int target=page;o.put("requestedSourceIds",cn.bidcheck.compat.Java8Api.listOf(c.all.stream().filter(s->s.evidence().page()==target).findFirst().orElseThrow(java.util.NoSuchElementException::new).id()));Map<String,Object> source=new LinkedHashMap<>((Map<String,Object>)o.get("source"));source.put("page",page);o.put("source",source);observations.add(o);}
        RuleEvaluator pending=evaluator(c,observations);assertEquals("UNDETERMINED",pending.evaluate(rule()).status());assertTrue(pending.visualRequests.stream().anyMatch(r->Integer.valueOf(10).equals(r.get("location"))));
        java.util.Map<java.lang.String, java.lang.Object> visible=observation(c);visible.put("id","last-visible");visible.put("location",10);visible.put("type","SEAL");visible.put("readability","CLEAR");visible.put("value",COMPANY);visible.put("observedValue",COMPANY);visible.put("sourceBbox",cn.bidcheck.compat.Java8Api.listOf(1, 1, 30, 30));Map<String,Object> source=new LinkedHashMap<>((Map<String,Object>)visible.get("source"));source.put("page",10);visible.put("source",source);visible.put("requestedSourceIds",cn.bidcheck.compat.Java8Api.listOf(c.all.stream().filter(s->s.evidence().page()==10).findFirst().orElseThrow(java.util.NoSuchElementException::new).id()));observations.add(visible);
        assertEquals("UNDETERMINED",evaluator(c,observations).evaluate(rule()).status());
    }
}
